WITH store_agg AS ( SELECT ss_item_sk, SUM(ss_net_profit) AS store_net_profit, SUM(ss_quantity) AS store_qty, SUM(ss_ext_sales_price) AS store_sales FROM store_sales GROUP BY ss_item_sk ), web_agg AS ( SELECT ws_item_sk, ws_web_site_sk, SUM(ws_net_profit) AS web_net_profit, SUM(ws_quantity) AS web_qty, SUM(ws_ext_sales_price) AS web_sales FROM web_sales GROUP BY ws_item_sk, ws_web_site_sk ) SELECT i.i_item_id, i.i_product_name, i.i_brand, i.i_category, ws.web_name, COALESCE(sa.store_net_profit,0) + COALESCE(wa.web_net_profit,0) AS total_net_profit, COALESCE(sa.store_qty,0) + COALESCE(wa.web_qty,0) AS total_quantity, CASE WHEN COALESCE(sa.store_net_profit,0) + COALESCE(wa.web_net_profit,0) > 100000 THEN 'High' WHEN COALESCE(sa.store_net_profit,0) + COALESCE(wa.web_net_profit,0) BETWEEN 50000 AND 100000 THEN 'Medium' ELSE 'Low' END AS profit_category, RANK() OVER (ORDER BY COALESCE(sa.store_net_profit,0) + COALESCE(wa.web_net_profit,0) DESC) AS profit_rank FROM item i LEFT JOIN store_agg sa ON i.i_item_sk = sa.ss_item_sk LEFT JOIN web_agg wa ON i.i_item_sk = wa.ws_item_sk LEFT JOIN web_site ws ON wa.ws_web_site_sk = ws.web_site_sk WHERE i.i_category = 'Sports' ORDER BY total_net_profit DESC LIMIT 10
